import type { Metadata } from "next"
import { routes, site } from "@/content/site"

export function absoluteUrl(path: string) {
  return new URL(path, site.url).toString()
}

// Generated by app/opengraph-image.tsx. Referenced explicitly because a page-level
// `openGraph` object replaces the root one, including its images.
const OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  type: "image/png",
  alt: "MailMind — je inbox gesorteerd, jij beslist",
}

/** Metadata with canonical URL and Open Graph for a route listed in content/site.ts. */
export function metadataFor(path: string): Metadata {
  const route = routes.find((r) => r.path === path)
  if (!route) throw new Error(`Route ontbreekt in content/site.ts: ${path}`)
  const isHome = path === "/"
  const fullTitle = isHome ? site.title : `${route.title} | ${site.name}`
  return {
    title: isHome ? { absolute: site.title } : route.title,
    description: route.description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      locale: site.locale,
      siteName: site.name,
      url: path,
      title: fullTitle,
      description: route.description,
      images: [OG_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description: route.description,
      images: [OG_IMAGE.url],
    },
  }
}
